import React from "react";
import Video from "../Video/Video";
import Anchor from "../Anchor/Anchor";

function SectionComopnent({ title, video, para, url}) {
  return (
    <div className=" relative  md:flex transition-all  m-5">
        <div className=" justify-center items-center md:flex md:flex-col mb-12">
          <h1 className=" text-4xl text-center mb-5 text-yellow-400">{title}</h1>
          <p className=" p-2 leading-relaxed text-lg">{para}</p>
          <div className=" flex justify-center">

          <Anchor text={"Explore More"} url={url}/>
          </div>
        </div>
        <Video video={video} />
    </div>
  );
}

export default SectionComopnent;
